function uniquePath(dir, filename) {
  const safe = path.basename(String(filename || '')).replace(/[<>:"/\\|?*\u0000-\u001f]/g, '_') || 'download';
  const ext = path.extname(safe);
  const base = path.basename(safe, ext);
  let candidate = path.join(dir, safe);
  let i = 1;
  while (fs.existsSync(candidate)) {
    candidate = path.join(dir, `${base} (${i})${ext}`);
    i += 1;
  }
  const root = path.resolve(dir);
  if (candidate !== root && !candidate.startsWith(root + path.sep)) return path.join(root, 'download');
  return candidate;
}

session.defaultSession.setPermissionCheckHandler((_wc, permission, _origin, details) => {
  if (permission === 'fullscreen') return true;
  return (details.requestingUrl || '').startsWith('https://');
});

session.defaultSession.setPermissionRequestHandler((_wc, permission, callback, details) => {
  const allowed = new Set(['fullscreen', 'pointerLock', 'accelerated-2d-canvas']);
  const secure = (details.requestingUrl || '').startsWith('https://');
  callback(allowed.has(permission) && secure);
});

session.defaultSession.setPermissionCheckHandler((_wc, permission, _origin, details) => {
  if (permission === 'fullscreen' || permission === 'pointerLock') return true;
  if (permission === 'media' || permission === 'clipboard-read' || permission === 'window-management') return false;
  return (details.requestingUrl || '').startsWith('https://');
});
